# Add to res://scenes/card/card_scene.gd:
signal card_dropped_on_discard(card_node: Control)

var is_dragging: bool = false
var drag_offset: Vector2 = Vector2.ZERO
var home_position: Vector2 = Vector2.ZERO

func _gui_input(event: InputEvent) -> void:
	if event is InputEventMouseButton and event.button_index == MOUSE_BUTTON_LEFT:
		if event.pressed:
			is_dragging = true
			home_position = position
			drag_offset = get_global_mouse_position() - global_position
			z_index = 20
		else:
			is_dragging = false
			z_index = 0
			var table := get_tree().current_scene
			var slot: Control = table.get_node_or_null("DiscardSlot") if table else null
			if slot != null and slot.get_global_rect().has_point(get_global_mouse_position()):
				card_dropped_on_discard.emit(self)
			else:
				create_tween().tween_property(self, "position", home_position, 0.14)
	elif event is InputEventMouseMotion and is_dragging:
		global_position = get_global_mouse_position() - drag_offset

# Hosting & Joining LAN Kadi + Syncing Moves via @rpc:
const PORT: int = 8910

func host_lan_game() -> void:
	var peer := ENetMultiplayerPeer.new()
	peer.create_server(PORT, 4)
	multiplayer.multiplayer_peer = peer

func join_lan_game(host_ip: String = "127.0.0.1") -> void:
	var peer := ENetMultiplayerPeer.new()
	peer.create_client(host_ip, PORT)
	multiplayer.multiplayer_peer = peer

@rpc("any_peer", "call_local", "reliable")
func rpc_commit_card_play(seat: int, suit: int, rank: int) -> void:
	var played := CardData.make(suit as CardTypes.Suits, rank)
	GameState.discard_pile.append(played)
	GameState.state_updated.emit()
	TurnManager.advance_turn()

